  expect(countdown(0)).toEqual([]);
});

hiddenTests:
test('a longer countdown', () => {
  expect(countdown(5)).toEqual([5, 4, 3, 2, 1]);
});
test('a negative number gives an empty array', () => {
  expect(countdown(-2)).toEqual([]);
});
test('length and the first and last element', () => {
  const result = countdown(10);
  expect(result).toHaveLength(10);
  expect(result[0]).toBe(10);
  expect(result[9]).toBe(1);
});

solutions.code:
function countdown(n) {
  const result = [];
  while (n > 0) {
    result.push(n);
    n--;
  }
  return result;
}
